import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";

export default function WithdrawForm({ onCancel }) {
  const [method, setMethod] = useState("bKash");
  const [receiverNumber, setReceiverNumber] = useState("");
  const [amount, setAmount] = useState("");
  const [balance, setBalance] = useState(null);
  const [message, setMessage] = useState("");
  const [loading, setLoading] = useState(false);

  const [otpSent, setOtpSent] = useState(false);
  const [otp, setOtp] = useState("");
  const [cooldown, setCooldown] = useState(0);

  const navigate = useNavigate();
  const token = localStorage.getItem("authToken");

  useEffect(() => {
    if (!token) {
      navigate("/");
      return;
    }
    fetch("http://localhost:8080/api/user/balance", {
      headers: { Authorization: `Bearer ${token}` },
    })
      .then((res) => res.ok && res.json())
      .then((data) => {
        if (data) setBalance(data.balance);
      })
      .catch(() => setMessage("❌ ব্যালেন্স লোড করতে সমস্যা হয়েছে।"));
  }, [token, navigate]);

  useEffect(() => {
    let timer;
    if (cooldown > 0) {
      timer = setInterval(() => {
        setCooldown((prev) => {
          if (prev <= 1) clearInterval(timer);
          return prev - 1;
        });
      }, 1000);
    }
    return () => clearInterval(timer);
  }, [cooldown]);

  const formatTime = (seconds) => {
    const m = Math.floor(seconds / 60);
    const s = seconds % 60;
    return `${m} মিনিট ${s} সেকেন্ড`;
  };

  const handleAmountChange = (e) => {
    const val = e.target.value;
    if (balance !== null && parseFloat(val) > balance) {
      setMessage(`❌ ব্যালেন্স পর্যাপ্ত নয়। আপনার ব্যালেন্স: ৳${balance.toFixed(2)}`);
    } else {
      setMessage("");
    }
    setAmount(val);
  };

  const handleSendOtp = async () => {
    if (!token) return;
    if (balance !== null && parseFloat(amount) > balance) {
      setMessage(`❌ ব্যালেন্স পর্যাপ্ত নয়। আপনার ব্যালেন্স: ৳${balance.toFixed(2)}`);
      return;
    }
    if (!receiverNumber || !amount) {
      setMessage("❌ অনুগ্রহ করে সকল ফিল্ড পূরণ করুন।");
      return;
    }
    if (cooldown > 0) {
      setMessage(`⏳ পরবর্তী অনুরোধের জন্য অপেক্ষা করুন: ${formatTime(cooldown)}`);
      return;
    }

    try {
      const res = await fetch("http://localhost:8080/api/withdraw/send-otp", {
        method: "POST",
        headers: { Authorization: `Bearer ${token}` },
      });

      const data = await res.json().catch(() => ({}));

      if (res.ok) {
        setOtpSent(true);
        setMessage("✅ OTP আপনার রেজিস্টার্ড মোবাইলে পাঠানো হয়েছে।");
      } else {
        if (data.remainingSeconds) {
          setCooldown(data.remainingSeconds);
          setMessage(`⏳ পরবর্তী অনুরোধের জন্য অপেক্ষা করুন: ${formatTime(data.remainingSeconds)}`);
        } else if (data.error) {
          setMessage("❌ " + data.error);
        } else {
          setMessage("❌ OTP পাঠাতে ব্যর্থ হয়েছে।");
        }
      }
    } catch (err) {
      setMessage("❌ নেটওয়ার্ক সমস্যা: " + err.message);
    }
  };

  const handleWithdraw = async (e) => {
    e.preventDefault();
    if (!otpSent) {
      setMessage("❌ অনুগ্রহ করে প্রথমে OTP অনুরোধ করুন।");
      return;
    }
    if (!otp) {
      setMessage("❌ অনুগ্রহ করে OTP লিখুন।");
      return;
    }

    setLoading(true);
    setMessage("");

    const payload = {
      method,
      receiverNumber,
      amount: parseFloat(amount),
      otp,
    };

    try {
      const res = await fetch("http://localhost:8080/api/withdraw/request", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify(payload),
      });

      if (res.ok) {
        setMessage("✅ প্রত্যাহারের অনুরোধ সফলভাবে পাঠানো হয়েছে!");
        setReceiverNumber("");
        setAmount("");
        setOtp("");
        setOtpSent(false);

        // ব্যালেন্স আপডেট করা
        const updatedBalanceRes = await fetch("http://localhost:8080/api/user/balance", {
          headers: { Authorization: `Bearer ${token}` },
        });
        if (updatedBalanceRes.ok) {
          const updatedData = await updatedBalanceRes.json();
          setBalance(updatedData.balance);
        }
      } else {
        const errorText = await res.text();
        setMessage("❌ প্রত্যাহার ব্যর্থ হয়েছে: " + errorText);
      }
    } catch (err) {
      setMessage("❌ নেটওয়ার্ক সমস্যা: " + err.message);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="flex justify-center items-center min-h-screen bg-gray-100 px-4">
      <form
        onSubmit={handleWithdraw}
        className="bg-white shadow-md rounded-xl w-full max-w-md p-6 space-y-5"
      >
        <h2 className="text-2xl font-bold text-center text-gray-800">
          🧾 প্রত্যাহারের অনুরোধ
        </h2>

        <div className="text-sm text-gray-700 text-center">
          আপনার ব্যালেন্স:{" "}
          <span className="font-semibold text-indigo-600">
            {balance !== null ? `৳ ${balance.toFixed(2)}` : "লোড হচ্ছে..."}
          </span>
        </div>

        <div>
          <label className="block text-gray-700 font-medium mb-1">পদ্ধতি</label>
          <select
            value={method}
            onChange={(e) => setMethod(e.target.value)}
            className="w-full px-4 py-2 border border-gray-300 rounded-lg"
          >
            <option value="bKash">bKash</option>
            <option value="Nagad">Nagad</option>
            <option value="Rocket">Rocket</option>
          </select>
        </div>

        <div>
          <label className="block text-gray-700 font-medium mb-1">রিসিভার নম্বর</label>
          <input
            type="text"
            value={receiverNumber}
            onChange={(e) => setReceiverNumber(e.target.value)}
            required
            placeholder="০১৭XXXXXXXX"
            className="w-full px-4 py-2 border border-gray-300 rounded-lg"
          />
        </div>

        <div>
          <label className="block text-gray-700 font-medium mb-1">পরিমাণ</label>
          <input
            type="number"
            step="0.01"
            value={amount}
            onChange={handleAmountChange}
            required
            placeholder="0.00"
            className="w-full px-4 py-2 border border-gray-300 rounded-lg"
          />
        </div>

        {otpSent && (
          <div>
            <label className="block text-gray-700 font-medium mb-1">OTP</label>
            <input
              type="text"
              value={otp}
              onChange={(e) => setOtp(e.target.value)}
              placeholder="৬-অঙ্কের OTP লিখুন"
              className="w-full px-4 py-2 border border-gray-300 rounded-lg"
            />
          </div>
        )}

        {message && (
          <div
            className={`text-sm text-center font-semibold p-3 rounded ${
              message.startsWith("✅")
                ? "bg-green-100 text-green-700"
                : message.startsWith("⏳")
                ? "bg-yellow-100 text-yellow-700"
                : "bg-red-100 text-red-700"
            }`}
          >
            {message}
          </div>
        )}

        <div className="flex gap-4 pt-2">
          {!otpSent ? (
            <button
              type="button"
              onClick={handleSendOtp}
              disabled={cooldown > 0}
              className="flex-1 bg-yellow-500 hover:bg-yellow-600 text-white font-semibold py-2 rounded-md transition"
            >
              {cooldown > 0 ? `অপেক্ষা করুন: ${formatTime(cooldown)}` : "📲 OTP পাঠান"}
            </button>
          ) : (
            <button
              type="submit"
              disabled={loading}
              className="flex-1 bg-indigo-600 hover:bg-indigo-700 text-white font-semibold py-2 rounded-md transition"
            >
              {loading ? "পাঠানো হচ্ছে..." : "অনুরোধ জমা দিন"}
            </button>
          )}

          <button
            type="button"
            onClick={onCancel}
            disabled={loading}
            className="flex-1 bg-gray-500 hover:bg-gray-600 text-white font-semibold py-2 rounded-md transition"
          >
            ⬅️ ব্যাক
          </button>
        </div>
      </form>
    </div>
  );
}
